package com.rtsbuilding.rtsbuilding.network.builder.handler;
import com.rtsbuilding.rtsbuilding.network.builder.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.util.EnumFacing;import net.minecraft.util.math.BlockPos;import net.minecraftforge.fml.common.network.simpleimpl.*;import java.lang.reflect.*;
/** 客户端只表达动作意图；实际物品、容器、掉落和方块状态始终由服务端重新解析。 */
public final class RtsActionControlHandlers{
 private static final String CAMERA="com.rtsbuilding.rtsbuilding.server.camera.RtsCameraManager",REGISTRY="com.rtsbuilding.rtsbuilding.server.service.ServiceRegistry",RECOVERY="com.rtsbuilding.rtsbuilding.server.service.RtsPlacedRecoveryService";
 private RtsActionControlHandlers(){}
 public static final class QuickDrop implements IMessageHandler<C2SRtsQuickDropPayload,IMessage>{public IMessage onMessage(final C2SRtsQuickDropPayload m,MessageContext c){if(!m.isValid())return null;schedule(c,new Action(){public void run(EntityPlayerMP p){if(range(p,m.dropPos()))service("transfer","quickDropLinkedItem",new Class<?>[]{EntityPlayerMP.class,String.class,byte.class,double.class,double.class,double.class},p,m.itemId(),m.amount(),m.dropX(),m.dropY(),m.dropZ());}});return null;}}
 public static final class Break implements IMessageHandler<C2SRtsBreakPayload,IMessage>{public IMessage onMessage(final C2SRtsBreakPayload m,MessageContext c){if(!m.isValid())return null;schedule(c,new Action(){public void run(EntityPlayerMP p){if(range(p,m.pos()))staticCall(RECOVERY,"breakPlaced",new Class<?>[]{EntityPlayerMP.class,BlockPos.class,EnumFacing.class,boolean.class},p,m.pos(),EnumFacing.byIndex(m.face()),m.allowAdjacentFallback());}});return null;}}
 public static final class StoreFluid implements IMessageHandler<C2SRtsStoreFluidPayload,IMessage>{public IMessage onMessage(final C2SRtsStoreFluidPayload m,MessageContext c){if(!m.isValid())return null;schedule(c,new Action(){public void run(EntityPlayerMP p){service("fluid","storeFluidFromContainer",new Class<?>[]{EntityPlayerMP.class,byte.class,byte.class,String.class},p,m.sourceType(),m.toolSlot(),m.itemId());}});return null;}}
 private interface Action{void run(EntityPlayerMP p);}private static void schedule(MessageContext c,final Action a){final EntityPlayerMP p=c.getServerHandler().player;p.getServerWorld().addScheduledTask(new Runnable(){public void run(){if(active(p))a.run(p);}});}
 private static boolean active(EntityPlayerMP p){return camera("isActive",new Class<?>[]{EntityPlayerMP.class},p);}private static boolean range(EntityPlayerMP p,BlockPos x){return camera("isWithinActionRange",new Class<?>[]{EntityPlayerMP.class,BlockPos.class},p,x);}
 private static boolean camera(String n,Class<?>[]t,Object...a){try{return Boolean.TRUE.equals(Class.forName(CAMERA).getMethod(n,t).invoke(null,a));}catch(ReflectiveOperationException e){throw fail("camera "+n,e);}}
 private static void service(String accessor,String name,Class<?>[]t,Object...a){try{Class<?>r=Class.forName(REGISTRY);Object i=r.getMethod("getInstance").invoke(null),s=r.getMethod(accessor).invoke(i);s.getClass().getMethod(name,t).invoke(s,a);}catch(ReflectiveOperationException e){throw fail(accessor+"."+name,e);}}
 private static void staticCall(String type,String name,Class<?>[]t,Object...a){try{Class.forName(type).getMethod(name,t).invoke(null,a);}catch(ReflectiveOperationException e){throw fail(name,e);}}
 private static RuntimeException fail(String m,ReflectiveOperationException e){Throwable c=e instanceof InvocationTargetException?((InvocationTargetException)e).getCause():e;return c instanceof RuntimeException?(RuntimeException)c:new IllegalStateException("1.12.2 adapter unavailable: "+m,c);}
}
